+import 'dart:convert';
+import 'dart:io';
+import 'dart:math';
+
+class User {
+  User(this.id, this.name, this.role);
+  final String id;
+  final String name;
+  final String role;
+}
+
+class Room {
+  Room(this.id, this.name, this.capacity);
+  final String id;
+  final String name;
+  final int capacity;
+  Map<String, Object> toJson() => {'id': id, 'nome': name, 'capacidade': capacity};
+}
+
+class Meeting {
+  Meeting(this.id, this.start, this.end);
+  final String id;
+  final DateTime start;
+  final DateTime end;
+}
+
+class Enrollment {
+  Enrollment(this.activityId, this.status);
+  final String activityId;
+  final String status;
+}
+
+class Activity {
+  Activity({required this.id, required this.title, required this.type, required this.roomId, required this.slots, required this.meetings});
