+  String title;
+  final String type;
+  final String roomId;
+  int slots;
+  final List<Meeting> meetings;
+  bool cancelled = false;
+}
+
+class ApiError {
+  ApiError(this.code, [this.message]);
+  final String code;
+  final String? message;
+  Map<String, String> toJson() => {'erro': code, 'mensagem': message ?? code};
+}
+
+DateTime _brasilia(DateTime instant) => instant.toUtc().subtract(const Duration(hours: 3));
+DateTime _parseDate(Object? value) => DateTime.parse(value as String).toUtc();
+String _formatDate(DateTime value) => value.toUtc().toIso8601String().replaceFirst(RegExp(r'\.000Z$'), 'Z');
+String _id(String prefix) => '$prefix${Random().nextInt(0x100000000).toRadixString(16).padLeft(8, '0')}';
+
+class ApiServer {
+  ApiServer({this.modoTeste = false}) { reset(); }
+  final bool modoTeste;
+  final users = <String, User>{};
+  final rooms = <String, Room>{};
+  final activities = <String, Activity>{};
+  final enrollments = <Enrollment>[];
+  late DateTime clock;
+
+  void reset() {
+    clock = DateTime.utc(2026, 10, 13, 12);
+    users
+      ..clear()
+      ..addAll({
+        'org-ana': User('org-ana', 'Ana Beatriz Lima', 'organizacao'),
+        'org-bruno': User('org-bruno', 'Bruno Tavares', 'organizacao'),
+        'p-carla': User('p-carla', 'Carla Mendes Souza', 'participante'),
+        'p-diego': User('p-diego', 'Diego Alves', 'participante'),
+        'p-elisa': User('p-elisa', 'Elisa Fernandes da Rocha', 'participante'),
+        'p-fabio': User('p-fabio', 'Fábio Nogueira', 'participante'),
+        'p-gabriela': User('p-gabriela', 'Gabriela Moura Castro', 'participante'),
+        'p-heitor': User('p-heitor', 'Heitor Campos', 'participante'),
+        'p-isadora': User('p-isadora', 'Isadora Ribeiro dos Santos', 'participante'),
+        'p-joao': User('p-joao', 'João Pedro Martins', 'participante'),
+      });
+    rooms
+      ..clear()
+      ..addAll({
+        'auditorio': Room('auditorio', 'Auditório Central', 200),
+        'sala-101': Room('sala-101', 'Sala 101', 40),
+        'sala-102': Room('sala-102', 'Sala 102', 40),
+        'lab-3': Room('lab-3', 'Laboratório 3', 20),
+      });
+    activities.clear();
+    enrollments.clear();
+  }
+
+  Future<void> handle(HttpRequest request) async {
+    request.response.headers
+      ..set('Access-Control-Allow-Origin', '*')
+      ..set('Access-Control-Allow-Headers', 'Content-Type, X-Usuario')
+      ..set('Access-Control-Allow-Methods', 'GET, POST, PATCH, PUT, OPTIONS');
+    if (request.method == 'OPTIONS') return _finish(request, 204);
+    try {
+      final path = request.uri.path;
+      if (path.startsWith('/_teste/')) return await _testRoute(request);
+      if (path == '/salas') return await _roomsRoute(request);
+      if (path == '/atividades') return await _activitiesRoute(request);
+      if (path.startsWith('/atividades/')) return await _activityRoute(request);
+      _finish(request, 404);
+    } catch (_) {
+      _json(request, 500, ApiError('ERRO_INTERNO').toJson());
+    }
+  }
+
+  Future<void> _testRoute(HttpRequest request) async {
+    if (!modoTeste) return _finish(request, 404);
+    if (request.uri.path == '/_teste/reset' && request.method == 'POST') {
+      reset();
+      return _finish(request, 204);
+    }
+    if (request.uri.path != '/_teste/relogio') return _finish(request, 404);
+    if (request.method == 'GET') return _json(request, 200, {'agora': _formatDate(clock)});
+    if (request.method != 'PUT') return _finish(request, 405);
+    final body = await _body(request);
+    if (body is! Map || body['agora'] is! String) return _error(request, 422, 'DADOS_INVALIDOS');
+    try {
+      clock = _parseDate(body['agora']);
+      return _json(request, 200, {'agora': _formatDate(clock)});
+    } catch (_) { return _error(request, 422, 'DADOS_INVALIDOS'); }
+  }
+
+  User? _user(HttpRequest request, {String? role}) {
+    final user = users[request.headers.value('X-Usuario')];
+    if (user == null) return null;
+    if (role != null && user.role != role) return User('', '__forbidden__', 'forbidden');
+    return user;
+  }
+  bool _authorized(HttpRequest request, String? role) {
+    final user = _user(request, role: role);
+    if (user == null) { _error(request, 401, 'USUARIO_DESCONHECIDO'); return false; }
+    if (user.role == 'forbidden') { _error(request, 403, 'SOMENTE_ORGANIZACAO'); return false; }
+    return true;
+  }
+
+  Future<void> _roomsRoute(HttpRequest request) async {
+    if (request.method != 'GET') return _finish(request, 405);
+    if (!_authorized(request, null)) return;
+    final result = rooms.values.toList()..sort((a, b) => a.id.compareTo(b.id));
+    _json(request, 200, result.map((room) => room.toJson()).toList());
+  }
+
+  Future<void> _activitiesRoute(HttpRequest request) async {
+    if (request.method == 'GET') return _list(request);
+    if (request.method == 'POST') return _create(request);
+    _finish(request, 405);
+  }
+
+  Future<void> _activityRoute(HttpRequest request) async {
+    final parts = request.uri.path.split('/').where((part) => part.isNotEmpty).toList();
+    if (parts.length < 2 || parts.length > 3) return _finish(request, 404);
+    final id = parts[1];
+    if (activities[id] == null) { if (!_authorized(request, request.method == 'GET' ? null : 'organizacao')) return; return _error(request, 404, 'NAO_ENCONTRADO'); }
+    if (parts.length == 3 && parts[2] == 'cancelamento' && request.method == 'POST') return _cancel(request, id);
+    if (parts.length != 2) return _finish(request, 404);
+    if (request.method == 'GET') return _detail(request, id);
+    if (request.method == 'PATCH') return _patch(request, id);
+    _finish(request, 405);
+  }
+
+  Future<void> _create(HttpRequest request) async {
+    if (!_authorized(request, 'organizacao')) return;
+    final body = await _body(request);
+    if (body is! Map || body['titulo'] is! String || body['tipo'] is! String || body['salaId'] is! String || body['vagas'] is! int || body['encontros'] is! List) return _error(request, 422, 'DADOS_INVALIDOS');
+    final meetings = _meetings(body['encontros'], createIds: true);
+    if (meetings == null) return _error(request, 422, 'DADOS_INVALIDOS');
+    final activity = Activity(id: _id('atv_'), title: body['titulo'] as String, type: body['tipo'] as String, roomId: body['salaId'] as String, slots: body['vagas'] as int, meetings: meetings);
+    final validation = _validateCreate(activity);
+    if (validation != null) return _error(request, validation == 'CONFLITO_DE_SALA' ? 409 : 422, validation);
+    activities[activity.id] = activity;
+    _json(request, 201, _activityJson(activity));
+  }
+
+  List<Meeting>? _meetings(Object value, {required bool createIds}) {
+    final list = value as List;
+    try {
+      return list.map((raw) {
+        if (raw is! Map || raw['inicio'] is! String || raw['fim'] is! String) throw const FormatException();
+        return Meeting(createIds ? _id('enc_') : '', _parseDate(raw['inicio']), _parseDate(raw['fim']));
+      }).toList()..sort((a, b) => a.start.compareTo(b.start));
+    } catch (_) { return null; }
+  }
+  String? _validateCreate(Activity activity) {
+    if (activity.type != 'palestra' && activity.type != 'minicurso') return 'DADOS_INVALIDOS';
+    if ((activity.type == 'palestra' && activity.meetings.length != 1) || (activity.type == 'minicurso' && (activity.meetings.length < 2 || activity.meetings.length > 5))) return 'QUANTIDADE_DE_ENCONTROS';
+    if (!_validMeetings(activity.meetings)) return 'ENCONTRO_INVALIDO';
+    final room = rooms[activity.roomId];
+    if (room == null) return 'DADOS_INVALIDOS';
+    if (activity.slots < 1) return 'DADOS_INVALIDOS';
+    if (activity.slots > room.capacity) return 'VAGAS_ACIMA_DA_CAPACIDADE';
+    if (_roomConflict(activity)) return 'CONFLITO_DE_SALA';
+    return null;
+  }
+  bool _validMeetings(List<Meeting> meetings) {
+    for (var i = 0; i < meetings.length; i++) {
+      final meeting = meetings[i];
+      final start = _brasilia(meeting.start), end = _brasilia(meeting.end);
+      if (start.year != 2026 || start.month != 10 || start.day < 19 || start.day > 23 || end.year != 2026 || end.month != 10 || end.day < 19 || end.day > 23) return false;
+      if (start.year != end.year || start.month != end.month || start.day != end.day) return false;
+      final duration = meeting.end.difference(meeting.start);
+      if (duration < const Duration(hours: 1) || duration > const Duration(hours: 4)) return false;
+      if (i > 0 && meetings[i - 1].end.isAfter(meeting.start)) return false;
+    }
+    return true;
+  }
+  bool _roomConflict(Activity candidate) {
+    for (final existing in activities.values) {
+      if (existing.cancelled || existing.roomId != candidate.roomId) continue;
+      for (final a in existing.meetings) for (final b in candidate.meetings) {
+        final overlap = a.start.isBefore(b.end) && b.start.isBefore(a.end);
+        final closeBefore = !a.end.isAfter(b.start) && b.start.difference(a.end) < const Duration(minutes: 15);
+        final closeAfter = !b.end.isAfter(a.start) && a.start.difference(b.end) < const Duration(minutes: 15);
+        if (overlap || closeBefore || closeAfter) return true;
+      }
+    }
+    return false;
+  }
+
+  Future<void> _list(HttpRequest request) async {
+    if (!_authorized(request, null)) return;
+    final type = request.uri.queryParameters['tipo'];
+    final day = request.uri.queryParameters['dia'];
+    final result = activities.values.where((activity) {
+      if (type != null && type.isNotEmpty && activity.type != type) return false;
+      if (day != null && day.isNotEmpty && !activity.meetings.any((meeting) => _brasilia(meeting.start).toIso8601String().startsWith(day))) return false;
+      return true;
+    }).toList();
+    result.sort((a, b) { final compare = a.meetings.first.start.compareTo(b.meetings.first.start); return compare == 0 ? a.title.compareTo(b.title) : compare; });
+    _json(request, 200, result.map(_activityJson).toList());
+  }
+  Future<void> _detail(HttpRequest request, String id) async { if (!_authorized(request, null)) return; _json(request, 200, _activityJson(activities[id]!)); }
+
+  Future<void> _patch(HttpRequest request, String id) async {
+    if (!_authorized(request, 'organizacao')) return;
+    final activity = activities[id]!;
+    final body = await _body(request);
+    if (body is! Map) return _error(request, 422, 'DADOS_INVALIDOS');
+    if (body.containsKey('salaId') || body.containsKey('tipo') || body.containsKey('encontros')) return _error(request, 422, 'CAMPO_NAO_EDITAVEL');
+    if (activity.cancelled) return _error(request, 422, 'ATIVIDADE_CANCELADA');
+    if (body.containsKey('titulo') && body['titulo'] is! String || body.containsKey('vagas') && body['vagas'] is! int) return _error(request, 422, 'DADOS_INVALIDOS');
+    if (body.containsKey('titulo')) activity.title = body['titulo'] as String;
+    if (body.containsKey('vagas')) {
+      final slots = body['vagas'] as int;
+      if (slots < 1) return _error(request, 422, 'DADOS_INVALIDOS');
+      if (slots > rooms[activity.roomId]!.capacity) return _error(request, 422, 'VAGAS_ACIMA_DA_CAPACIDADE');
+      if (slots < _occupied(activity.id)) return _error(request, 409, 'VAGAS_ABAIXO_DOS_INSCRITOS');
+      activity.slots = slots;
+    }
+    _json(request, 200, _activityJson(activity));
+  }
+  Future<void> _cancel(HttpRequest request, String id) async {
+    if (!_authorized(request, 'organizacao')) return;
+    final activity = activities[id]!;
+    if (activity.cancelled) return _error(request, 422, 'ATIVIDADE_CANCELADA');
+    if (!clock.isBefore(activity.meetings.first.start)) return _error(request, 422, 'ATIVIDADE_JA_INICIADA');
+    activity.cancelled = true;
+    _json(request, 200, _activityJson(activity));
+  }
+
+  int _occupied(String id) => enrollments.where((e) => e.activityId == id && (e.status == 'confirmada' || e.status == 'convocada')).length;
+  int _waiting(String id) => enrollments.where((e) => e.activityId == id && e.status == 'em_espera').length;
+  Map<String, Object> _activityJson(Activity activity) {
+    final meetings = [...activity.meetings]..sort((a, b) => a.start.compareTo(b.start));
+    final situation = activity.cancelled ? 'cancelada' : clock.isBefore(meetings.first.start) ? 'prevista' : !clock.isBefore(meetings.last.end) ? 'encerrada' : 'em_andamento';
+    return {'id': activity.id, 'titulo': activity.title, 'tipo': activity.type, 'salaId': activity.roomId, 'vagas': activity.slots, 'encontros': meetings.map((m) => {'id': m.id, 'inicio': _formatDate(m.start), 'fim': _formatDate(m.end)}).toList(), 'cargaHorariaMinutos': meetings.fold<int>(0, (sum, m) => sum + m.end.difference(m.start).inMinutes), 'situacao': situation, 'ocupadas': _occupied(activity.id), 'vagasRestantes': activity.slots - _occupied(activity.id), 'emEspera': _waiting(activity.id)};
+  }
+
+  Future<Object?> _body(HttpRequest request) async {
+    final text = await utf8.decoder.bind(request).join();
+    if (text.trim().isEmpty) return null;
+    try {
+      final value = jsonDecode(text);
+      if (value is! Map && value is! List) return null;
+      return value;
+    } catch (_) { return null; }
+  }
+  void _error(HttpRequest request, int status, String code) => _json(request, status, ApiError(code).toJson());
+  void _json(HttpRequest request, int status, Object body) { request.response.headers.contentType = ContentType.json; request.response.statusCode = status; request.response.write(jsonEncode(body)); request.response.close(); }
+  void _finish(HttpRequest request, int status) { request.response.statusCode = status; request.response.close(); }
+}

