+Future<Response> request(ApiServer api, String method, String path, {String? user, Object? body}) async {
+  final server = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
+  server.listen(api.handle);
+  final client = HttpClient();
+  final request = await client.openUrl(method, Uri.parse('http://127.0.0.1:${server.port}$path'));
+  if (user != null) request.headers.set('X-Usuario', user);
+  if (body != null) { request.headers.contentType = ContentType.json; request.write(body is String ? body : jsonEncode(body)); }
+  final response = await request.close();
+  final text = await utf8.decoder.bind(response).join();
+  await server.close(force: true);
+  client.close(force: true);
+  return Response(response.statusCode, text);
+}
+
+class Response {
+  Response(this.status, this.text);
+  final int status;
+  final String text;
+  dynamic get json => text.isEmpty ? null : jsonDecode(text);
+}
