       if (slots > rooms[activity.roomId]!.capacity)
         return _error(request, 422, 'VAGAS_ACIMA_DA_CAPACIDADE');
       if (slots < _occupied(activity.id))
         return _error(request, 409, 'VAGAS_ABAIXO_DOS_INSCRITOS');
